function maxPower(s) {
  let best = 1;
  let run = 1;

  for (let i = 1; i < s.length; i++) {
    if (s[i] === s[i - 1]) {
      run++;
    } else {
      run = 1;
    }
    best = Math.max(best, run);
  }
  return best;
}

