function maxPower(s) {
  let answer = 0;
  for (let start = 0; start < s.length; start++)
    for (let end = start + 1; end <= s.length; end++) {
      const piece = s.slice(start, end);
      if (new Set(piece).size === 1) answer = Math.max(answer, piece.length);
    }
  return answer;
}

