function generate(rand, size) {
  const n = size === 'large' ? 400 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 12);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alphabet = 1 + Math.floor(rand() * (size === 'large' ? 26 : 4));
  const offset = Math.floor(rand() * (26 - alphabet + 1));
  const maxRun = 1 + Math.floor(rand() * (size === 'large' ? 60 : 5));
  let s = '';
  while (s.length < n) {
    const ch = letters[offset + Math.floor(rand() * alphabet)];
    const run = 1 + Math.floor(rand() * maxRun);
    s += ch.repeat(Math.min(run, n - s.length));
  }
  return [s];
}
